function inventory(){
  let all=active();
  let brands=[...new Set(all.map(x=>x.brand).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'));
  let rows=all.filter(x=>(!filter.life||x.lifecycle===filter.life)&&(!filter.color||(filter.color==='pending'?!x.color_family:x.color_family===filter.color))&&(!filter.brand||x.brand===filter.brand)&&matchTime(days(x),filter.time));
  rows.sort((a,b)=>sort==='expiry'?(days(a)??1e9)-(days(b)??1e9):sort==='color'?String(a.color_family).localeCompare(String(b.color_family)):sort==='brand'?String(a.brand).localeCompare(String(b.brand),'zh-CN'):b.created_at-a.created_at);
  let selectedFilter=Object.values(filter).some(Boolean);
  shell(`<div class="heading"><div><div class="eyebrow">YOUR PERSONAL COLLECTION</div><h1>我的口红柜</h1><p class="sub">让每一抹喜欢，都被好好记得。</p></div><button class="primary" onclick="newItem()">＋ 录入口红</button></div>
  <div class="stats"><button class="stat" onclick="resetFilter()"><div><span>当前持有</span><b>${all.length}</b> <small>支</small></div><i>▱</i></button><button class="stat" onclick="filter.life='opened';render()"><div><span>已开封</span><b>${all.filter(x=>x.lifecycle==='opened').length}</b> <small>支</small></div><i>◔</i></button><button class="stat" onclick="filter.time='30';render()"><div><span>30天内到期 · 含今日</span><b>${all.filter(x=>days(x)!==null&&days(x)>=0&&days(x)<=30).length}</b> <small>支</small></div><i>◷</i></button></div>
  <div class="toolbar"><span class="count">${selectedFilter?'筛选结果':'全部口红'} · ${rows.length} 支</span>${selectedFilter?'<button class="text-btn" onclick="resetFilter()">清除筛选</button>':''}<button class="secondary" onclick="filtersOpen=!filtersOpen;render()">☷ 筛选${selectedFilter?' · 已选':''}</button><select aria-label="排序" onchange="sort=this.value;render()">${options([['new','最近录入'],['expiry','到期日期优先'],['brand','按品牌'],['color','按色系']],sort)}</select></div>
  ${filtersOpen?`<div class="filter-panel filter-panel-four"><label>期限状态<select aria-label="期限状态筛选" onchange="filter.time=this.value;render()">${options([['','全部期限'],['180+','超过180天'],['180','91–180天'],['90','31–90天'],['30','30天内到期（含今日）'],['expired','已到期'],['unknown','期限待补充']],filter.time)}</select></label><label>开封状态<select aria-label="开封状态筛选" onchange="filter.life=this.value;render()">${options([['','全部状态'],['opened','已开封'],['unopened','未开封'],['unknown','待补充']],filter.life)}</select></label><label>色系<select aria-label="色系筛选" onchange="filter.color=this.value;render()">${options([['','全部色系'],...families.map(x=>[x[0],x[1]]),['pending','待分类']],filter.color)}</select></label><label>品牌<select aria-label="品牌筛选" onchange="filter.brand=this.value;render()">${options([['','全部品牌'],...brands.map(x=>[x,x])],filter.brand||'')}</select></label></div>`:''}
  ${rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:`<div class="empty"><h2>${all.length?'没有符合条件的口红':'给喜欢的口红，一个位置'}</h2><p>${all.length?'试试调整筛选条件。':'拍下整体与底部色号，开始整理你的收藏。'}</p><button class="primary" onclick="${all.length?'resetFilter()':'newItem()'}">${all.length?'清除筛选':'录入第一支'}</button></div>`}<div class="footer-note">实拍记录你的收藏 · 期限仅作提醒，不代表品质检测</div>${demoControls()}`)
}

function timeline(x){
  let opened=x.opened_on||'', end=deadline(x)||'', created=iso(new Date(x.created_at||Date.now()));
  let hasOpened=x.lifecycle==='opened'&&opened;
  return `<div class="timeline" aria-label="产品时间轴"><div class="timeline-line"></div><div class="timeline-step done"><i>✓</i><b>录入日期</b><span>${created}</span></div><div class="timeline-step ${hasOpened?'done':'pending'}"><i>${hasOpened?'✓':'○'}</i><b>开封日期</b><span>${hasOpened?opened:(x.lifecycle==='unopened'?'尚未开封':'未记录')}</span></div><div class="timeline-step ${end?'end':'pending'}"><i>${end?'◷':'○'}</i><b>到期日期</b><span>${end||'待补充'}</span></div></div>`
}

function detail(){
  let x=items.find(x=>x.id===selected);if(!x){navAction('inventory');return}
  let n=days(x),p=period(n),e=expiry(x),op=addMonths(x.opened_on,x.pao_months);
  shell(`<button class="back" onclick="navAction(origin)">← 返回${origin==='compare'?'买前查看':'口红柜'}</button><div class="detail-grid"><div><div class="detail-image">${visual(x,true)}</div><p class="hint">${x.images?.length?'你的实拍记录':'示意插画 · 非真实产品照片'}</p>${x.images?.length>1?`<div class="thumbs">${x.images.map((im,i)=>`<button class="thumb" onclick="setCover('${x.id}',${i})" title="设为封面"><img src="${im}" alt="照片${i+1}"></button>`).join('')}</div><p class="hint">点击缩略图设为封面</p>`:''}</div>
  <div class="detail-content"><h1 class="product-title">${esc(x.display_name)}</h1><div class="product-meta"><span>${esc(x.brand||'品牌未记录')}</span><span>${esc(x.series||'系列未记录')}</span><span>${esc(x.shade_code||'色号未记录')}</span></div><div class="status-tags"><span class="tag">${life[x.lifecycle]}</span><span class="tag ${p[1]}">${p[0]}</span><span class="tag">${fam(x.color_family)?.[1]||'待分类'}</span></div>
  <div class="panel expiry-card"><div class="expiry-head"><div><span class="section-label">USE PERIOD</span><h3>使用期限</h3></div><div class="date-big ${p[1]}">${n===null?'—':Math.abs(n)} <small>${n===null?'期限待补充':n<0?'天前已到期':'天剩余'}</small></div></div>${timeline(x)}<div class="basis-line">${op&&e?'按开封后期限与产品到期日的较早值计算':op?'按开封后期限计算':e?(x.expires_on?'按实物到期日期':'按生产日期与保质期推算'):'暂无足够期限信息'}</div><details><summary>查看日期与来源依据</summary><p>开封后使用期限：${x.pao_months?x.pao_months+'个月':'未知'}${x.pao_source?`（${esc(x.pao_source)}）`:''}<br>开封计算到期日：${op||'未知'}<br>实物标注到期日：${x.expires_on||'未记录'}<br>生产日期：${x.manufactured_on||'未记录'}<br>未开封保质期：${x.shelf_life_months?x.shelf_life_months+'个月':'未知'}<br>日期仅供管理提醒，不代表实物品质检测。</p></details></div>
  ${x.note?`<div class="panel"><h3>我的备注</h3><p class="sub">${esc(x.note)}</p></div>`:''}<div class="detail-action-bar" aria-label="产品操作"><button class="detail-action icon-action" onclick="editItem('${x.id}')" aria-label="编辑产品信息" title="编辑产品信息"><span aria-hidden="true">✎</span></button><button class="detail-action discard-action" onclick="removeItem('${x.id}','discarded')"><span aria-hidden="true">⌫</span> 移出库存</button></div><button class="delete-link" onclick="deleteItem('${x.id}')">删除记录</button></div></div>`)
}

function paoBlock(busy){
  if(draft.lifecycle!=='opened')return '';
  if(busy&&!draft.pao_months)return `<div class="pao-result loading-source"><span>正在获取开封后使用期限</span><small>从包装照片和对应产品资料中核对…</small></div>`;
  if(draft.pao_months)return `<div class="pao-result"><div><span>开封后使用期限</span><b>${esc(draft.pao_months)} 个月</b></div><small>来源：${esc(draft.pao_source||'包装照片／产品资料（待用户核对）')}</small><button class="text-btn" onclick="draft.pao_manual=!draft.pao_manual;renderForm()">修改</button></div>${draft.pao_manual?field('修改开封后使用期限（月）','pao_months','number','修改后以你的确认值为准。'):''}`;
  return `<div class="pao-result missing-source"><span>未获取到可靠的开封后使用期限</span><small>可重新拍摄包装标识、重试查询，或手动补充。</small><div class="actions"><button class="secondary" onclick="runAI()">重新获取</button><button class="text-btn" onclick="draft.pao_manual=true;renderForm()">手动补充</button></div></div>${draft.pao_manual?field('开封后使用期限（月）','pao_months','number'):''}`
}

function renderForm(){
  if(!draft)return;let focused=document.activeElement;let focusKey=focused?.getAttribute('oninput');let caret=focused?.selectionStart;let scrollY=window.scrollY;let busy=['识别中','查询资料中'].includes(aiStatus);
  shell(`<div class="form-wrap"><button class="back" onclick="navigate('inventory')">← 返回口红柜</button><div class="form-head"><div class="eyebrow">MAKE ROOM FOR YOUR FAVORITES</div><h1>${draft.revision?'编辑口红':'录入一支喜欢'}</h1><p class="sub">上传后就能填写开封信息，识别结果稍后自动补齐。</p></div>
  <div class="form-panel"><div class="section-label">01 / PHOTOS</div><h2>先拍下它</h2><label class="upload-zone"><input type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="upload(this.files)"><span style="font-size:25px;color:#a7857c">＋</span><b>上传整体图与底部色号</b><small>有包装可补拍日期与开封后期限标记<br>最多3张 · JPG / PNG / WebP · 每张10MB以内</small></label>${draft.images.length?`<div class="thumbs">${draft.images.map((im,i)=>`<div class="thumb"><img src="${im}" alt="已上传照片${i+1}"><button aria-label="移除照片" onclick="draft.images.splice(${i},1);upd('images',draft.images);renderForm()">×</button></div>`).join('')}</div>`:''}<div class="actions"><button class="secondary" ${busy?'disabled':''} onclick="runAI()">${draft.images.length?'重新模拟识别':'体验模拟识别'}</button><select aria-label="模拟结果" onchange="aiMode=this.value">${options([['success','模拟：正常结果'],['partial','模拟：部分成功'],['fail','模拟：查询失败'],['ambiguous','模拟：身份歧义']],aiMode)}</select></div><div class="ai-box">✧ ${aiStatus||'AI 识别为模拟演示，照片不会发送到外部服务。'} ${busy?'<button class="text-btn" onclick="task++;aiStatus=\'已取消，可继续手动填写\';renderForm()">取消</button>':''}${aiStatus==='需要确认产品身份'?'<div class="actions"><button class="secondary" onclick="applyAI();aiStatus=\'已选择演示系列，结果请核对\';renderForm()">演示品牌 · 唇色系列 R03</button><button class="text-btn" onclick="aiStatus=\'请手动填写产品身份\';renderForm()">都不是，手动填写</button></div>':''}</div></div>
  <div class="form-panel"><div class="section-label">02 / OPENING DATE</div><h2>它开封了吗？</h2><div class="seg">${['opened','unopened','unknown'].map(k=>`<button class="${draft.lifecycle===k?'active':''}" onclick="upd('lifecycle','${k}');renderForm()">${life[k]}</button>`).join('')}</div>${draft.lifecycle==='opened'?`${field('开封日期','opened_on','date','不记得具体日期可留空，不会擅自按今天计算。')}<button class="text-btn" onclick="upd('opened_on','');renderForm()">不记得开封日期</button>`:'<p class="hint">未开封时无需填写开封后使用期限；之后开封可在详情页更新。</p>'}</div>
  <div class="form-panel"><div class="section-label">03 / PRODUCT DETAILS</div><h2>确认产品信息</h2>${field('名称 *','display_name')}<div class="two">${field('品牌','brand')}${field('系列','series')}${field('色号','shade_code')}<label class="field">色系 · 请确认<select onchange="upd('color_family',this.value)">${options([['','待分类'],...families.map(f=>[f[0],f[1]+' · '+f[2]])],draft.color_family)}</select><small>AI先建议，以你的选择为准。</small></label>${field('质地','texture')}</div></div>
  <div class="form-panel"><div class="section-label">04 / DATES & NOTES</div><h2>${draft.lifecycle==='opened'?'期限信息':'产品期限与备注'}</h2>${paoBlock(busy)}<div class="two">${field('实物标注到期日','expires_on','date')}${draft.lifecycle==='opened'?'':'<div class="hint field">未开封状态只记录产品到期信息，不展示开封后期限。</div>'}</div><details ${draft.manufactured_on?'open':''}><summary>只有生产日期？补充推算信息</summary><div class="two" style="margin-top:18px">${field('实物生产日期','manufactured_on','date')}${field('未开封保质期（月）','shelf_life_months','number')}</div></details><label class="field" style="margin-top:22px">备注<textarea rows="3" maxlength="500" oninput="upd('note',this.value)">${esc(draft.note)}</textarea></label><p class="hint">日期由你核对确认；模拟识别不会生成真实产品的保质期。</p></div>${error?`<div class="inline-error" role="alert">${esc(error)}</div>`:''}<div class="form-foot"><button class="secondary" onclick="confirmBox('放弃这次修改？','未保存的信息将被清除，已有库存不受影响。',()=>{task++;localStorage.removeItem(DRAFT);dirty=false;draft=null;navAction('inventory')},'放弃修改')">取消录入</button><button class="primary" onclick="saveItem()">确认并保存</button></div></div>`);
  if(focusKey){let el=[...document.querySelectorAll('[oninput]')].find(e=>e.getAttribute('oninput')===focusKey);if(el){el.focus({preventScroll:true});try{el.setSelectionRange(caret,caret)}catch{}}}window.scrollTo(0,scrollY)
}

function applyAI(){
  if(!draft)return;let suggestions={display_name:'玫瑰绒雾（模拟结果）',brand:'ATELIER · 演示品牌',series:'唇色系列',shade_code:'R03',color_family:'rose',texture:'哑光'};
  if(draft.lifecycle==='opened'){suggestions.pao_months='12';suggestions.pao_source='包装 12M 标识／官网产品资料（模拟）'}
  for(let [k,v]of Object.entries(suggestions)){if(!draft[k])draft[k]=v}draft.mock=true;dirty=true;saveDraft()
}

function runAI(){
  let t=++task;aiStatus='识别中';renderForm();setTimeout(()=>{if(t!==task||view!=='form')return;aiStatus='查询资料中';renderForm()},700);setTimeout(()=>{if(t!==task||view!=='form')return;if(aiMode==='fail')aiStatus='查询未完成，已保留输入。可重试或手动填写。';else if(aiMode==='ambiguous')aiStatus='需要确认产品身份';else{applyAI();if(aiMode==='partial'){draft.pao_months='';draft.pao_source='';aiStatus='已识别产品，但未获取到可靠期限来源。'}else aiStatus='模拟结果已补齐，请核对品牌、色号、色系和期限来源。'}renderForm()},1700)
}

render();
